 if(scene["strategy"]=="image_native"){unsigned count=0,characters=0;for(auto c:components){count+=unsigned(c["features"].toArray().size());for(auto f:c["features"].toArray())characters+=unsigned(f.toString().size());}need(components.size()<=48&&count<=96&&characters<=6000&&p["spatial"].toArray().size()<=64&&p["rubric"].toArray().size()<=16,"visual-review-budget-capacity");}
