void validateVisualDetail(const QJsonObject&s,const QString&question){auto q=question.toLower();if(s["category"]=="route"&&QRegularExpression("\\bmap\\b").match(q).hasMatch()&&!QRegularExpression("route[ -]?graph").match(q).hasMatch())need(false,"visual-map-requested-route-graph");auto detail=s["plan"].toObject()["detail"].toString();if(s["version"]==4&&QRegularExpression("\\blabel\\w*\\b").match(q).hasMatch()){bool found=false;for(auto value:s["plan"].toObject()["picture"].toObject()["spec"].toObject()["components"].toArray()){auto c=value.toObject();if(c["role"]=="part"){found=true;need(!c["label"].isNull(),"picture-requested-label-missing");}}need(found,"picture-requested-parts-missing");}else if(s["strategy"]=="image_native"&&QRegularExpression("\\blabel\\w*\\b").match(q).hasMatch()){QSet<QString> labelled;for(auto v:s["objects"].toArray())if(v.toObject()["kind"]=="label")labelled.insert(v.toObject()["parent"].toString());for(auto v:s["plan"].toObject()["components"].toArray()){auto c=v.toObject();if(c["role"]!="background"&&c["role"]!="orientation"&&c["role"]!="route"&&(s["version"]!=3||(c["role"]!="subject"&&c["role"]!="region")))need(labelled.contains(c["id"].toString()),"visual-requested-label-missing");}}if(QRegularExpression("\\b(highly detailed|intricate|photorealistic)\\b").match(q).hasMatch())need(detail=="highly-detailed","visual-detail-downgraded");else if(QRegularExpression("\\b(detailed|realistic|anatomical|professional|textbook)\\b").match(q).hasMatch())need(detail=="detailed"||detail=="highly-detailed","visual-detail-downgraded");else if(detail=="simple")need(QRegularExpression("\\b(simple|quick|rough|minimal|stick.figure)\\b").match(q).hasMatch(),"visual-default-detail-too-low");}
